"""Group aggregates with null values, repeated amounts, and HAVING."""
import random
SCAFFOLD='''import sqlite3

def solve(data):
    connection = sqlite3.connect(":memory:")
    connection.row_factory = sqlite3.Row
    try:
        connection.execute("CREATE TABLE entries(id INTEGER PRIMARY KEY, account TEXT NOT NULL, amount INTEGER, kind TEXT NOT NULL)")
        connection.executemany("INSERT INTO entries VALUES (?, ?, ?, ?)", [(r["id"], r["account"], r["amount"], r["kind"]) for r in data["rows"]])
        return [dict(r) for r in summary_rows(connection, data["minimum_total"], data["minimum_events"])]
    finally:
        connection.close()

'''
QUERY='''def summary_rows(connection, minimum_total, minimum_events):
    return connection.execute("SELECT account, COUNT(*) AS events, COUNT(amount) AS valued, COALESCE(SUM(amount), 0) AS total FROM entries WHERE kind = 'paid' GROUP BY account HAVING COALESCE(SUM(amount), 0) >= ? AND COUNT(*) >= ? ORDER BY total DESC, account ASC", (minimum_total, minimum_events)).fetchall()
'''
JAVA='''public Object solve(Map<String,Object> d){
    Map<String,long[]> groups=new HashMap<>();for(Object value:arr(d.get("rows"))){Map<String,Object> r=obj(value);if(!s(r.get("kind")).equals("paid"))continue;long[] g=groups.computeIfAbsent(s(r.get("account")),k->new long[3]);g[0]++;if(r.get("amount")!=null){g[1]++;g[2]+=lng(r.get("amount"));}}
    List<Object> out=new ArrayList<>();for(Map.Entry<String,long[]> e:groups.entrySet()){long[] g=e.getValue();if(g[0]>=n(d.get("minimum_events"))&&g[2]>=lng(d.get("minimum_total")))out.add(map("account",e.getKey(),"events",g[0],"valued",g[1],"total",g[2]));}
    out.sort(Comparator.comparingLong((Object v)->lng(obj(v).get("total"))).reversed().thenComparing(v->s(obj(v).get("account"))));return out;
}'''
def row(i,a,amount,kind="paid"):return {"id":i,"account":a,"amount":amount,"kind":kind}
def result(a,events,valued,total):return {"account":a,"events":events,"valued":valued,"total":total}
def case(rows,expected,label,total=0,events=1):return {"input":{"rows":rows,"minimum_total":total,"minimum_events":events},"expected":expected,"label":label}
CASES=[case([row(1,"a",10),row(2,"a",10),row(3,"a",None)],[result("a",3,2,20)],"repeated amounts count and null affects only valued count"),case([row(1,"a",4),row(2,"a",6),row(3,"b",20)],[result("a",2,2,10)],"HAVING applies both group thresholds",total=10,events=2),case([row(1,"a",None),row(2,"a",None)],[result("a",2,0,0)],"all-null sum becomes zero"),case([],[],"empty table"),case([row(1,"a",100,"void")],[],"void rows form no group"),case([row(1,"a",0)],[result("a",1,1,0)],"zero is a valued amount"),case([row(1,"a",5),row(2,"a",100,"void")],[],"void rows do not meet event threshold",events=2),case([row(1,"a",-2),row(2,"a",-3)],[result("a",2,2,-5)],"negative total threshold",total=-5),case([row(1,"b",10),row(2,"a",10)],[result("a",1,1,10),result("b",1,1,10)],"account resolves total ties"),case([row(1,"a",1),row(2,"z",9)],[result("z",1,1,9),result("a",1,1,1)],"descending totals"),case([row(1,"a",9)],[],"group below minimum total",total=10),case([row(1,"A",5),row(2,"a",5)],[result("A",1,1,5),result("a",1,1,5)],"case-sensitive grouping and ASCII order"),case([row(1,"a",8),row(2,"a",-8)],[result("a",2,2,0)],"positive and negative offset"),case([row(1,"O'Reilly",3)],[result("O'Reilly",1,1,3)],"quoted account value")]
R=random.Random(33)
GENERATED=[{"rows":[row(j,["a","b","A"][(i+j)%3],R.choice([None,-5,0,5,5,10]),R.choice(["paid","paid","void"])) for j in range(1,i+3)],"minimum_total":i-7,"minimum_events":i%4+1} for i in range(18)]
SPEC={"number":33,"slug":"sql-group-having","title":"Summarize groups without losing NULL meaning","difficulty":"Medium","time":35,"prerequisites":"Problems 31–32; filtering, NULL, and deterministic output order.","learn":"Aggregation combines several rows into one summary. WHERE selects source rows before grouping. HAVING selects completed groups using aggregate values. COUNT(*) counts rows, while COUNT(amount) counts only rows whose amount is not NULL. SUM ignores NULL amounts and returns NULL when every amount in a group is NULL. A report can explicitly replace that result with zero through COALESCE. Equal amounts in different entries are still separate business events. Adding DISTINCT would change their meaning. This exercise asks for both row count and known-value count so that missing amounts remain visible even when the displayed total defaults to zero.","task":"Complete `summary_rows(connection, minimum_total, minimum_events)`. The scaffold loads `entries(id PRIMARY KEY, account, amount nullable, kind)` from `rows`. First keep only kind paid. Group by exact account string. For each group calculate events as all paid rows, valued as paid rows with non-null amount, and total as the sum of non-null amounts, or zero if all are null. Keep groups with total at least minimum_total and events at least minimum_events. Accounts with no paid rows do not form groups. Return `{account, events, valued, total}` rows ordered by total descending, then account ascending with SQLite's default binary ordering. Use SQL aggregation and HAVING with bound thresholds. The reference executes SQLite. The output judge cannot enforce SQL use or the chosen clauses.","constraints":["0–300 rows with unique ids from 1 through 1000000.","account is a nonempty printable ASCII string of at most 40 characters. kind is paid or void.","amount is null or an integer in [-1000000,1000000]. minimum_total is in [-300000000,300000000]; minimum_events is 1–300."],"hints":["COUNT(*) and COUNT(amount) answer different questions.","Apply the same COALESCE sum rule to the displayed total and the HAVING condition."],"starter":SCAFFOLD+"def summary_rows(connection, minimum_total, minimum_events):\n    raise NotImplementedError\n","reference":SCAFFOLD+QUERY,"java":JAVA,"approach":"Filter paid entries, group by account, compute the three aggregates, then apply HAVING. Repeated values are retained. A typical implementation scans n rows and groups with temporary storage; sorting g output groups takes O(g log g). Overall work can be O(n log n), depending on the query plan. Production reports must separately define how unknown amounts affect business decisions.","cases":CASES,"generated":GENERATED,"mutations":[{"name":"deduplicate equal payment amounts","old":"SUM(amount)","new":"SUM(DISTINCT amount)","count":2}],"sources":["https://www.sqlite.org/lang_aggfunc.html","https://www.sqlite.org/lang_select.html#resultset"]}
